{
  "state": "App liên tục bị đơ khi thanh toán, tôi muốn được hoàn tiền lại vào tài khoản!",
  "questions": {
    "intent": {
      "type": "choice",
      "instructions": "Xác định nhu cầu chính của khách hàng:",
      "criteria": {
        "refund": "Yêu cầu hoàn trả tiền / khiếu nại cước phí",
        "check_system_ram": "Hỏi tài nguyên bộ nhớ RAM",
        "check_temperature": "Hỏi nhiệt độ hệ thống",
        "other": "Các vấn đề khác"
      }
    },
    "frustrated": {
      "type": "noul",
      "instructions": "Khách hàng có đang cảm thấy bực mình hoặc khó chịu không?"
    }
  },
  "auto_trigger": true
}

{
  "state": "Cảnh báo khẩn cấp: Cơ sở dữ liệu sập toàn tập, toàn bộ giao dịch người dùng bị gián đoạn nghiêm trọng!",
  "questions": {
    "incident_severity": {
      "type": "choice",
      "instructions": "Mức độ nghiêm trọng của sự cố:",
      "criteria": {
        "critical": "Sự cố tê liệt toàn hệ thống hoặc mất dữ liệu nghiêm trọng",
        "warning": "Cảnh báo quá tải hoặc suy giảm hiệu năng nhẹ",
        "info": "Thông tin vận hành thông thường"
      }
    }
  },
  "auto_trigger": true
}

{
  "state": "Tôi muốn gửi thông báo chấm dứt hợp đồng dịch vụ và đóng tài khoản.",
  "questions": {
    "action_target": {
      "type": "choice",
      "instructions": "Phân loại phòng ban xử lý:",
      "criteria": {
        "finance_invoice": "Kế toán & Hóa đơn VAT",
        "tech_bug": "Bộ phận Kỹ thuật & Báo lỗi phần mềm",
        "contract_termination": "Bộ phận Pháp chế & Hủy hợp đồng / Rời dịch vụ",
        "sales_consult": "Tư vấn mua thêm gói cước / Upsell",
        "security_incident": "Báo cáo an toàn thông tin & Hack",
        "hr_recruitment": "Tuyển dụng nhân sự và ứng tuyển việc làm",
        "general_feedback": "Góp ý cải thiện dịch vụ chung"
      }
    }
  },
  "k": 3,
  "auto_trigger": false
}

{
  "text": "Mô hình System 1 phân loại ý định người dùng với độ trễ cực thấp dưới hai mươi mili giây."
}

{
  "name": "Gửi thông báo Telegram khi phát hiện gian lận",
  "description": "Tự động gọi webhook khi model phát hiện fraud",
  "active": true,
  "require_approval": false,
  "trigger": {
    "question_key": "is_fraud",
    "match_noul": true,
    "min_confidence": 0.8
  },
  "action": {
    "type": "api",
    "url": "https://httpbin.org/post",
    "method": "POST",
    "headers": {
      "Content-Type": "application/json"
    },
    "auth": {
      "type": "bearer",
      "token": "tele_bot_secret_token"
    },
    "json_body": {
      "alert": "Phát hiện gian lận giao dịch!",
      "details": "{{context.state}}"
    },
    "timeout": 10
  }
}
